          },
          "briefTitle": "COLORECTUM+ Digital System for Postoperative Quality Improvement in Colorectal Cancer",
          "officialTitle": "Construction and Application of a Digital Postoperative Medical Quality Evaluation and Promotion System for Colorectal Cancer Based on the COLORECTUM+ Model"
        },
        "statusModule": {
          "statusVerifiedDate": "2026-07",
          "overallStatus": "RECRUITING",
          "expandedAccessInfo": {
            "hasExpandedAccess": false
          },
          "startDateStruct": {
