            "type": "ACTUAL"
          },
          "lastUpdateSubmitDate": "2026-07-27",
          "lastUpdatePostDateStruct": {
            "date": "2026-07-28",
            "type": "ACTUAL"
          }
        },
        "sponsorCollaboratorsModule": {
          "responsibleParty": {
            "type": "SPONSOR"
          },
          "leadSponsor": {
            "name": "RenJi Hospital",
            "class": "OTHER"
          },
          "collaborators": [
            {
              "name": "Shanghai Shen Kang Hospital Development Center",
              "class": "OTHER"
            }
          ]
        },
        "oversightModule": {
          "oversightHasDmc": true,
          "isFdaRegulatedDrug": false,
          "isFdaRegulatedDevice": false
        },
        "descriptionModule": {
          "briefSummary": "This is a single-center, prospective, interventional study. A total of 236 colorectal cancer patients who underwent surgery will be enrolled and followed for 52 weeks. The digital healthcare quality management system, based on the COLORECTUM+ model, will be used for post-treatment quality evaluation and continuous improvement.\n\nPatients will be managed using an Internet+ post-treatment healthcare management platform. The platform integrates AI technology for real-time symptom analysis and alerts. Patients will report symptoms and health data through the platform, which will generate alerts based on symptom severity to guide appropriate interventions. Follow-up assessments will include patient adherence, satisfaction, quality of life, and healthcare utilization.\n\nThe study expects to demonstrate that the digital healthcare quality management system improves follow-up rates, enhances patient adherence, reduces unplanned hospital visits, and increases overall patient satisfaction. The findings aim to provide evidence for the implementation of digital management systems in colorectal cancer post-treatment care, potentially leading to improved long-term outcomes for patients.",
          "detailedDescription": "The aim of this study is to evaluate the adherence of postoperative colorectal cancer patients using a digital follow-up platform. The primary endpoint is follow-up rate at 3 months after surgery. The secondary endpoints are: follow-up rate at 6, 9, and 12 months, adherence during 12 months, medication adherence (MMS-4), the number and reasons for alerts triggered by patients, the frequency and reasons for patient-initiated report, quality of life (FACT-C), patient satisfaction (FACIT-TS-PS), the system's usability (SUS), the monitoring rates of imaging exams, colonoscopies, and CEA markers at 3, 6, 9, and 12 months will be analyzed. Differences in clinical outcomes: progression-free survival, overall survival, adverse events, the incidence of complications, hospital admissions (unplanned hospital visit rates, average unplanned hospital stay duration, and potentially preventable emergency visits) are additional outcomes."
        },
        "conditionsModule": {
          "conditions": [
            "Colorectal Carcinoma"
          ],
          "keywords": [
            "colorectal carcinoma",
            "follow-up",
            "Ehealth",
            "adherence"
          ]
        },
        "designModule": {
          "studyType": "INTERVENTIONAL",
          "phases": [
            "NA"
          ],
          "designInfo": {
            "allocation": "NA",
            "interventionModel": "SINGLE_GROUP",
            "primaryPurpose": "OTHER",
            "maskingInfo": {
              "masking": "NONE"
            }
          },
          "enrollmentInfo": {
            "count": 236,
            "type": "ESTIMATED"
          }
        },
        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "experimental group",
              "type": "EXPERIMENTAL",
              "description": "Colorectal cancer patients enrolled in the 'Internet Plus' post-treatment management platform use the digital medical quality management system based on the 'COLORECTUM+' model for quality evaluation and continuous improvement. The platform integrates AI, using natural language processing and machine learning to analyze patient-reported symptoms, automatically assess severity, and generate alerts. Alerts are classified as yellow, orange, or red. Yellow indicates mild issues with self-care recommendations; consecutive yellow alerts prompt doctor contact within 24 hours. Orange indicates moderate severity, requiring doctor intervention within 24 hours. Red alerts signify serious symptoms or high-risk medication errors, prompting immediate notification of the doctor and emergency team. The system monitors symptom changes and updates alerts to support treatment optimization.",
              "interventionNames": [
                "Device: Mobile application follow-up"
              ]
            }
          ],
          "interventions": [
            {
              "type": "DEVICE",
              "name": "Mobile application follow-up",
              "description": "Colorectal cancer patients enrolled in the 'Internet Plus' post-treatment management platform use the digital medical quality management system based on the 'COLORECTUM+' model for quality evaluation and continuous improvement. The platform integrates AI, using natural language processing and machine learning to analyze patient-reported symptoms, automatically assess severity, and generate alerts. Alerts are classified as yellow, orange, or red. Yellow indicates mild issues with self-care recommendations; consecutive yellow alerts prompt doctor contact within 24 hours. Orange indicates moderate severity, requiring doctor intervention within 24 hours. Red alerts signify serious symptoms or high-risk medication errors, prompting immediate notification of the doctor and emergency team. The system monitors symptom changes and updates alerts to support treatment optimization.",
              "armGroupLabels": [
                "experimental group"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "three-month follow-up rate",
              "description": "Our mobile application aims to monitor the three-month follow-up rate for patients, assessing whether they adhere to the follow-up schedule as outlined，providing a streamlined approach to track post-discharge appointments. By utilizing real-time notifications and easy scheduling features, the app encourages patients to attend their follow-up visits, ensuring continuity of care. The application records and analyzes data on scheduled and completed appointments within three months post-discharge, offering insights into adherence rates and identifying factors impacting follow-up compliance. This data-driven approach helps healthcare providers improve patient outcomes and optimize follow-up strategies.",
              "timeFrame": "At 12 weeks after enrollment."
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "adherance",
              "description": "User adherence with the mHealth intervention will be measured by following approaches\n\n1. User log-in data retrieved from app or website：\n\n   * Number of log-ins to app\n   * Length of time spent in app\n2. Manual user data entry in app - The frequency at which users manually enter data in the app, such as blood glucose level, weight, date and time when medicine was taken, or blood pressure values.",
              "timeFrame": "From enrollment to the end of treatment at 52 weeks, patient adherence will be assessed at each visit."
            },
            {
              "measure": "Quality of life",
              "description": "Quality of life (QoL) was captured by survey with the 27-Item Functional Assessment of Cancer Therapy-Colorectal (FACT-C), which consists of 27 items with physical component summary and mental component summary scores. The score range is 0 to 136, with higher scores indicating better quality of life.",
              "timeFrame": "From enrollment to the end of treatment at 52 weeks"
            },
            {
              "measure": "Average unplanned hospitalization days",
              "description": "Unplanned Hospitalization Days\" refers to the duration of hospital stays that occur outside of a patient's scheduled follow-up plan. These unplanned admissions indicate instances where a patient's condition requires urgent or unexpected inpatient care, reflecting potential health complications or acute needs beyond the regular follow-up schedule. Monitoring unplanned hospitalization days can provide valuable insights into patient health outcomes, care management, and the effectiveness of follow-up programs.",
              "timeFrame": "The 3rd, 6th, 9th, and 12th months after enrollment"
            },
            {
              "measure": "Potentially preventable emergency department visits",
              "description": "\"Potentially Preventable Emergency Visits\" are defined as emergency visits where the primary diagnoses include conditions such as anemia, nausea, fever, dehydration, neutropenia, diarrhea, pain, pneumonia, sepsis, or vomiting. These visits represent cases where timely outpatient care, effective management, or preventive measures might have reduced the need for emergency intervention. Tracking potentially preventable emergency visits helps healthcare providers identify areas for improvement in outpatient management and preventive care, ultimately aiming to reduce avoidable strain on emergency services.",
              "timeFrame": "The 3rd, 6th, 9th, and 12th months after enrollment"
            },
            {
              "measure": "Number and distribution of alerts",
              "description": "\"Number and Distribution of Alerts\" involves collecting patient-reported symptoms, medication information, and health data such as tumor markers and imaging results through symptom questionnaires and patient self-reports. When risks or abnormalities are detected, alerts are automatically triggered. Alerts are categorized by urgency and severity into yellow, orange, and red levels. Descriptive statistical methods are used to analyze alert occurrences, with frequencies and percentages summarizing the number and reasons for each alert type. The average number of alerts triggered per patient, along with the standard deviation, is calculated. Correlation or regression analyses are applied to explore relationships between the number of alerts and other variables.",
              "timeFrame": "The 3rd, 6th, 9th, and 12th months after enrollment"
            },
